import{z as n,x as p,o as i,c as o,q as s,j as l,D as e,d as A,s as E,S as r}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"ACD 自回归条件久期","description":"","frontmatter":{"title":"ACD 自回归条件久期","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/acd-duration.md","filePath":"quant/acd-duration.md","lastUpdated":1791063341000}'),B={name:"quant/acd-duration.md"};function d(_,a,D,C,u,h){const t=p("Mermaid");return i(),o("div",null,[a[2]||(a[2]=s('<h1 id="acd-自回归条件久期" tabindex="-1">ACD 自回归条件久期 <a class="header-anchor" href="#acd-自回归条件久期" aria-label="Permalink to &quot;ACD 自回归条件久期&quot;">​</a></h1><div class="epigraph"><p>相邻两笔事件的等待时间不是独立的指数抽签：刚刚很短的久期，往往预示着下一笔也会来得快。把这个条件期望写成自回归，久期就有了与 GARCH 对偶的结构。</p><footer>—— Engle and Russell, Autoregressive Conditional Duration: A New Model for Irregularly Spaced Transaction Data, Econometrica, 1998</footer></div><p><a href="/quant/multivariate-hawkes">多元 Hawkes</a>把互激写进事件类型之间的强度；间隔本身的计量是另一条路。Hawkes 从强度 \\(\\lambda(t)\\) 出发，事件在强度高的时候更密集。<a href="/quant/irregular-sampling">不等间隔采样</a> 已经提到，Engle 与 Russell 选择对偶的对象：<strong>久期</strong> \\(x_i=t_i-t_{i-1}\\)，即相邻成交（或相邻报价修订）的墙钟间隔。自回归条件久期（Autoregressive Conditional Duration, ACD）令 \\(x_i=\\psi_i\\varepsilon_i\\)，其中 \\(\\psi_i=\\mathbb{E}[x_i\\mid\\mathcal{F}_{i-1}]\\) 随过去的久期与过去的 \\(\\psi\\) 演化，\\(\\varepsilon_i\\) 是正值新息。本篇写 ACD 的设定、与 Hawkes 的翻译、以及它在微观结构里能回答的「下一笔何时来」，而不是「下一笔什么价」。它补成交 Hawkes 没展开的久期计量，不重复核函数与分支比的全部内容。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日历网格上的 GARCH 假设等间隔收益。成交点过程的间隔从毫秒到分钟，等间隔模型要么插入零收益，要么丢掉空洞。直接对 \\(x_i\\) 建模，样本就是事件本身。朴素做法是假设 \\(x_i\\) 独立指数，等价于常数泊松——这正是真实数据拒绝的：久期有强烈的自相关，开盘短、午间长，爆发成串。问题是找到一个像 GARCH 那样可估计、可诊断的条件均值，使标准化残差 \\(x_i/\\psi_i\\) 接近 i.i.d.。</p><p>第二个问题是对象：成交久期、报价久期、还是价格发生变化的久期。Engle–Russell 的原始应用包括价格久期（price duration）：只有当价格移动至少 \\(c\\) 才记一步，用来连到交易强度与波动。混用三种久期会让系数不可比。A 股还要决定午休是删失、切断还是当成一个超长 \\(x_i\\)——第三种会毁掉整个 \\(\\psi\\) 的自回归。</p><p><span class="marginnote">用数字看第三种有多糟：把 90 分钟午休当成一个超长 \\(x_i\\)，等于让一次抽签把 \\(\\psi\\) 拉到 \\(5400\\) 秒的量级；按 \\(\\alpha+\\beta\\approx0.98\\) 的持续性，这个假信号要拖几十笔才衰减完，随后的全部条件均值都被污染。正确做法是午休处直接切断序列。</span></p><h3 id="acd-1-1-与指数新息" tabindex="-1">ACD(1,1) 与指数新息 <a class="header-anchor" href="#acd-1-1-与指数新息" aria-label="Permalink to &quot;ACD(1,1) 与指数新息&quot;">​</a></h3><p>标准 ACD(1,1) 为</p> \\[\\psi_i=\\omega+\\alpha x_{i-1}+\\beta\\psi_{i-1},\\qquad x_i=\\psi_i\\varepsilon_i,\\quad \\mathbb{E}[\\varepsilon_i]=1. \\]<p>\\(\\varepsilon\\) 取指数、Weibull 或广义伽马。指数对应无记忆的标准化等待；Weibull 允许风险率随等待时间上升或下降。平稳性要求 \\(\\alpha+\\beta\\lt 1\\)（在这一线性式里）。\\(\\alpha+\\beta\\) 接近 1 表示久期的持续性强：忙的状态会持续，闲的状态也会持续。这与 Hawkes 分支比接近 1 是对偶现象的两种参数化，数值上不能直接划等号，因为一个积分的是核，一个自回归的是间隔。</p><p><span class="marginnote">\\(\\psi_i\\) 是条件期望间隔，强度的粗糙对偶是 \\(1/\\psi_i\\)。只有在新息为指数、且强度在两次事件之间为常数时，这种对偶才精确。Hawkes 的强度在事件之间是连续衰减的，ACD 默认在两次事件之间把条件均值钉住，这是离散时间标记的代价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计用极大似然，密度由 \\(\\varepsilon\\) 的选择与 \\(\\psi_i\\) 的递归给出。必须先去掉日内季节性：开盘、午间、收盘的确定性 U 形（或倒 U 形）久期，否则 \\(\\alpha,\\beta\\) 会去拟合时钟。常用做法是先把 \\(x_i\\) 除以时段样条或日内分箱均值，再对去季节后的序列估 ACD。残差诊断：标准化久期的自相关应消失；若 Weibull 形状参数显著偏离 1，指数新息不够。</p><p><span class="marginnote">「日内 U 形」就是确定性节奏：开盘与收盘附近成交密集（久期天然短）、午间稀疏（久期天然长）。若不先除掉它，模型会把「现在是上午 9:35」当成「市场很忙」，估出来的持续性其实是时钟的持续性，不是市场自身的。</span></p><p>标记 ACD 把成交量、方向放进 \\(\\psi\\) 或放进新息的尺度：大成交之后期望久期更短，对应自激。这是通向 Hawkes 的桥梁，但仍是事件时钟上的回归，不是连续强度。Engle 后来的 ACD-GARCH 把去季节久期与收益波动连起来：交易密的时候波动高。对象若是执行，ACD 给出「还要等多久可能有一笔对手方市价」，是 <a href="/quant/fill-probability">成交概率</a> 里市价流的约化描述；它不给出对手方会不会打在你这一档。</p><h3 id="价格久期与波动" tabindex="-1">价格久期与波动 <a class="header-anchor" href="#价格久期与波动" aria-label="Permalink to &quot;价格久期与波动&quot;">​</a></h3><p>价格久期把点过程稀化：只有 \\(|\\Delta p|\\ge c\\) 才记录。\\(c\\) 取一个 tick 或几个 tick。稀化后的 ACD 描述价格移动的等待，强度 \\(1/\\psi\\) 与瞬时波动同向。\\(c\\) 太大，样本变短、丢失微观结构；\\(c\\) 太小，又回到几乎每笔都记录，价格久期不再提供新信息。报告必须锁定 \\(c\\)，并说明是否在事件时间里对中间价还是成交价。中间价的闪烁会制造假的短久期，通常应要求 BBO 两侧都移动或中点移动至少半个 tick 且持续。</p><p>与 <a href="/quant/volume-imbalance-bars">成交量不平衡条</a> 的差别：不平衡条按累积净量切样本，ACD 按时间间隔建模。前者改变下标，后者解释下标之间的墙钟。可以在 VIB 的条内再看平均久期，但不要把 ACD 的 \\(\\psi\\) 当成封条规则。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制上，短久期成串来自同一组微观结构力：算法切片把母单拆成密集成交、公告与开盘把所有人的强度抬高、Hawkes 式的反馈让一笔成交引来下一笔。ACD 不指出是哪一种，它只要求条件均值可预测。这是优点也是缺点：拟合好、诊断清楚，但对「内生还是外生」沉默。要拆开，需要把公告放进 \\(\\psi\\) 的外生回归项，或改用 Hawkes 并把公告放进 \\(\\mu(t)\\)。</p><p>久期与买卖方向的联合，才接近信息模型。若短久期时方向更持续，更像知情或动量切片；若短久期时方向对冲，更像双边忙碌的做市。Engle–Russell 的框架可以扩成带方向的标记，但经典 ACD 论文本身不承担 PIN 的识别。毒性仍要不平衡与事后价差。</p><h3 id="与-hawkes-何时该换表示" tabindex="-1">与 Hawkes 何时该换表示 <a class="header-anchor" href="#与-hawkes-何时该换表示" aria-label="Permalink to &quot;与 Hawkes 何时该换表示&quot;">​</a></h3><p>事件极密、核的衰减发生在两次事件之间（毫秒级指数核、事件间隔也是毫秒），连续强度 Hawkes 更自然，因为 ACD 把两次事件之间的强度钉死。事件较稀、关心的是「下一笔成交要等几秒」、并且要与 GARCH 式的诊断文化对接时，ACD 更方便。二者不是竞争理论，是同一点过程的两种离散/连续记账。残差若在 ACD 之后仍有长记忆，可加分整 ACD 或改用慢核 Hawkes；先不要把 \\(\\alpha+\\beta=0.99\\) 写成「市场临界」。</p><p><span class="marginnote">初学者容易把 \\(\\alpha+\\beta\\) 接近 1 解读成「市场接近临界、要崩了」；它只说明久期的持续性高——忙会接着忙、闲会接着闲——本身与危机无关。把持续性强等同于临界，需要分支比、厚尾、幂律等多重证据，一个参数接近 1 远远不够。</span></p>',25)),(i(),l(r,null,{default:e(()=>[E(t,{id:"mermaid-71",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%E8%A6%81%E4%BB%80%E4%B9%88%22%5D%20--%3E%20A%5B%22%E4%B8%8B%E4%B8%80%E7%AC%94%E8%A6%81%E7%AD%89%E5%87%A0%E7%A7%92%20%E4%B8%8E%20GARCH%20%E8%AF%8A%E6%96%AD%E5%AF%B9%E6%8E%A5%22%5D%0A%20%20Q%20--%3E%20B%5B%22%E6%AF%AB%E7%A7%92%E7%BA%A7%E5%AF%86%E5%BA%A6%20%E5%BC%BA%E5%BA%A6%E5%9C%A8%E9%97%B4%E9%9A%94%E5%86%85%E8%A1%B0%E5%87%8F%22%5D%0A%20%20A%20--%3E%20C%5B%22%E7%94%A8%20ACD%20%E7%A6%BB%E6%95%A3%E8%AE%B0%E8%B4%A6%22%5D%0A%20%20B%20--%3E%20D%5B%22%E7%94%A8%20Hawkes%20%E8%BF%9E%E7%BB%AD%E5%BC%BA%E5%BA%A6%22%5D%0A%20%20C%20--%3E%20E%5B%22%E6%A3%80%E6%9F%A5%E6%A0%87%E5%87%86%E5%8C%96%E6%AE%8B%E5%B7%AE%E8%87%AA%E7%9B%B8%E5%85%B3%22%5D%0A%20%20D%20--%3E%20E%0A%20%20E%20--%3E%20F%7B%22%E6%AE%8B%E5%B7%AE%E8%BF%98%E6%9C%89%E9%95%BF%E8%AE%B0%E5%BF%86%3F%22%7D%0A%20%20F%20--%3E%7C%E6%98%AF%7C%20G%5B%22%E5%88%86%E6%95%B4%20ACD%20%E6%88%96%E6%85%A2%E6%A0%B8%20Hawkes%22%5D%0A%20%20F%20--%3E%7C%E5%90%A6%7C%20H%5B%22%E6%A8%A1%E5%9E%8B%E5%8F%AF%E4%BA%A4%E4%BB%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<p>这张图回答的问题是：面对同一个事件流，什么时候用 ACD、什么时候换 Hawkes，以及换模型的判据放在残差诊断而不是直觉上。</p><p><span class="marginnote"><a href="/quant/multivariate-hawkes">多元 Hawkes</a> 处理的是类型之间的激励。多元 ACD、或 Engle 的自回归条件密度，可以对向量久期建模，但维数与识别都更绕。类型依赖优先用多元点过程。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>ACD 假定观测到每一次相关事件。馈送丢包会制造假的长久期，把 \\(\\psi\\) 拉高。用本地到达时间而不是撮合时间，会把网络抖动写进微观结构。涨跌停板上成交间隔的含义变成「还有没有排队成交」，不是连续强度。集合竞价只有一个匹配时刻，没有连续久期。</p><p>不要用 ACD 去填日历网格再跑等间隔因子：那是把点过程的条件均值插值成假的规则采样。不要在未去季节的原始秒间隔上报告「很强的持续性」——那多半是开盘效应。新息分布若有过离散，指数似然会误导标准误；应至少报告 Weibull 对照。</p><p><span class="marginnote">久期模型回答何时，不回答能否成交、以什么价成交。把它接到执行，还缺队列位置与深度。ACD 可以给市价到达的时钟，不能单独给缺口。</span></p>',6)),(i(),l(r,null,{default:e(()=>[E(t,{id:"mermaid-90",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E8%BF%87%E5%8E%BB%E4%B9%85%E6%9C%9F%20x_%7Bi-1%7D%22%5D%20--%3E%20Psi%5B%22%E6%9D%A1%E4%BB%B6%E5%9D%87%E5%80%BC%20%CF%88_i%22%5D%0A%20%20Psi0%5B%22%CF%88_%7Bi-1%7D%22%5D%20--%3E%20Psi%0A%20%20Seas%5B%22%E6%97%A5%E5%86%85%E5%AD%A3%E8%8A%82%20%2F%20%E5%85%AC%E5%91%8A%22%5D%20--%3E%20Psi%0A%20%20Psi%20--%3E%20Draw%5B%22x_i%20%3D%20%CF%88_i%20%CE%B5_i%22%5D%0A%20%20Draw%20--%3E%20Next%5B%22%E4%B8%8B%E4%B8%80%E4%BA%8B%E4%BB%B6%E6%97%B6%E5%88%BB%22%5D%0A%20%20Next%20--%3E%20X%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ACD 对事件间隔的条件均值做自回归，是不等间隔成交数据上与 GARCH 对偶的计量结构。</li><li>必须先去掉日内季节性；午休应切断而不是当成一个超长间隔。</li><li>标准化残差应接近 i.i.d.；Weibull 新息检验无记忆假设。</li><li>价格久期把点过程按最小价格变动稀化，用于连接交易强度与波动。</li><li>与 Hawkes：ACD 钉住事件间的条件均值，Hawkes 允许强度在间隔内衰减；密过程优先连续强度。</li><li>出处：Engle and Russell, <em>Econometrica</em>, 1998。</li></ul>',2))])}const b=n(B,[["render",d]]);export{m as __pageData,b as default};
